# Dungeon Travelers 2-2 (PC, English) - Balance mod: the changes to the program file.
# Generated by mod_project/tools/package_variant.py from the sheet ExePatches. Do not edit the tables below.
#
#   Patch_Program.bat      writes the changes (a copy of each program file is kept beside it first)
#   Unpatch_Program.bat    puts the original bytes back
#
# Run it from the folder of the game (the one that holds the .exe). The game must be closed.
param([string]$Mode = 'patch')

$ErrorActionPreference = 'Stop'
$here = Split-Path -Parent $MyInvocation.MyCommand.Path

# file name -> rows of (offset in the file, original bytes, new bytes), in hexadecimal
$tables = @{
#TABLES#
}

function To-Bytes([string]$hex) {
    $bytes = New-Object byte[] ($hex.Length / 2)
    for ($i = 0; $i -lt $bytes.Length; $i++) { $bytes[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
    return ,$bytes
}

function Holds([byte[]]$data, [int]$offset, [byte[]]$bytes) {
    for ($i = 0; $i -lt $bytes.Length; $i++) { if ($data[$offset + $i] -ne $bytes[$i]) { return $false } }
    return $true
}

$found = 0
foreach ($name in $tables.Keys) {
    $path = Join-Path $here $name
    if (-not (Test-Path $path)) { continue }
    $found++
    $data = [System.IO.File]::ReadAllBytes($path)
    $from = if ($Mode -eq 'patch') { 1 } else { 2 }
    $to = if ($Mode -eq 'patch') { 2 } else { 1 }
    $todo = 0
    $wrong = 0
    foreach ($row in $tables[$name]) {
        $offset = [Convert]::ToInt32($row[0], 16)
        if (Holds $data $offset (To-Bytes $row[$to])) { continue }
        if (Holds $data $offset (To-Bytes $row[$from])) { $todo++ } else { $wrong++ }
    }
    if ($wrong -gt 0) {
        Write-Host "$name : not the version this mod was made for ($wrong places differ). Nothing was written."
        continue
    }
    if ($todo -eq 0) {
        Write-Host "$name : nothing to do, it is already as asked."
        continue
    }
    if ($Mode -eq 'patch') {
        $copy = "$path.original"
        if (-not (Test-Path $copy)) { [System.IO.File]::WriteAllBytes($copy, $data) }
    }
    foreach ($row in $tables[$name]) {
        $offset = [Convert]::ToInt32($row[0], 16)
        $bytes = To-Bytes $row[$to]
        for ($i = 0; $i -lt $bytes.Length; $i++) { $data[$offset + $i] = $bytes[$i] }
    }
    try {
        [System.IO.File]::WriteAllBytes($path, $data)
        Write-Host "$name : done ($todo places)."
    } catch {
        Write-Host "$name : could not be written. Close the game and run this again."
    }
}
if ($found -eq 0) { Write-Host "No program file of the game here. Put these files in the folder of the game, beside its .exe." }
